CREATE TABLE IF NOT EXISTS clients(Id INT PRIMARY KEY,Name VARCHAR(180),IsActive BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS employees(Id INT PRIMARY KEY,ClientId INT NOT NULL,EmployeeCode VARCHAR(80),FirstName VARCHAR(100),LastName VARCHAR(100),IsActive BOOLEAN NOT NULL DEFAULT TRUE,WorkLocationId INT NOT NULL DEFAULT 0,ReportingManagerUserId INT NULL);
CREATE TABLE IF NOT EXISTS employee_it0000_actions(Id INT PRIMARY KEY AUTO_INCREMENT,EmployeeId INT,ClientId INT,ActionType VARCHAR(30),Status VARCHAR(30),EffectiveFrom DATE);
CREATE TABLE IF NOT EXISTS modulesettings(client_id INT,ModuleCode VARCHAR(80),SettingsJson JSON);
CREATE TABLE IF NOT EXISTS attendance_settings(id INT PRIMARY KEY AUTO_INCREMENT,client_id INT,shift_id INT NULL,check_in_time TIME DEFAULT '09:00:00',check_out_time TIME DEFAULT '18:00:00',working_hours_calculation VARCHAR(80) DEFAULT 'First check-in and last check-out',minimum_hours_for_half_day DECIMAL(5,2) DEFAULT 4,minimum_hours_for_full_day DECIMAL(5,2) DEFAULT 8,maximum_hours_allowed_for_full_day DECIMAL(5,2) DEFAULT 12,allow_regularization_requests BOOLEAN DEFAULT TRUE,regularization_window VARCHAR(40) DEFAULT 'Anytime',past_days_allowed INT DEFAULT 7,restrict_regularization_requests_per_month BOOLEAN DEFAULT FALSE,max_regularization_requests_per_month INT DEFAULT 3,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS attendance_shifts(id INT PRIMARY KEY,client_id INT,shift_code VARCHAR(50),shift_name VARCHAR(180),shift_type VARCHAR(20),start_time TIME,end_time TIME,is_overnight BOOLEAN,grace_minutes INT,break_minutes INT,minimum_full_day_hours DECIMAL(5,2),minimum_half_day_hours DECIMAL(5,2),effective_from DATE,effective_to DATE,is_active BOOLEAN,rules_json JSON,created_at DATETIME,updated_at DATETIME);
CREATE TABLE IF NOT EXISTS attendance_groups(id INT PRIMARY KEY,client_id INT,shift_id INT,attendance_mode VARCHAR(20),allowed_shift_ids_json JSON,is_active BOOLEAN,work_week VARCHAR(80),attendance_cycle_start_day INT,attendance_cycle_end_day INT,work_location_id INT);
CREATE TABLE IF NOT EXISTS attendance_group_employees(attendance_group_id INT,employee_id INT);
CREATE TABLE IF NOT EXISTS attendance_shift_assignments(id INT PRIMARY KEY,client_id INT,employee_id INT,shift_id INT,effective_from DATE,effective_to DATE,week_days VARCHAR(20),reason VARCHAR(500),is_active BOOLEAN);
CREATE TABLE IF NOT EXISTS payruns(Id INT PRIMARY KEY,ClientId INT,PayPeriod VARCHAR(7),Status VARCHAR(30));
CREATE TABLE IF NOT EXISTS payrunemployees(PayRunId INT,EmployeeId INT);
CREATE TABLE IF NOT EXISTS employee_attendance_punches(id BIGINT PRIMARY KEY AUTO_INCREMENT,client_id INT,employee_id INT,client_request_id VARCHAR(100),action VARCHAR(20),captured_at DATETIME,latitude DECIMAL(10,7),longitude DECIMAL(10,7),accuracy_meters INT,geo_fence_rule_id INT NULL,distance_meters DECIMAL(10,2) NULL,effective_radius_meters INT NULL,outside_by_meters DECIMAL(10,2) NULL,validation_status VARCHAR(60),decision VARCHAR(30),reason VARCHAR(600),face_verified BOOLEAN,face_match_score DECIMAL(6,3),liveness_score DECIMAL(6,3),face_provider VARCHAR(80),face_reference_id VARCHAR(180),device_id VARCHAR(180),network_type VARCHAR(40),app_version VARCHAR(80),camera_capture_confirmed BOOLEAN,biometric_confirmed BOOLEAN,device_model VARCHAR(180),os_version VARCHAR(80),UNIQUE KEY ux_request(client_id,employee_id,client_request_id));
CREATE TABLE IF NOT EXISTS employee_daily_attendance(id INT PRIMARY KEY AUTO_INCREMENT,client_id INT,employee_id INT,attendance_date DATE,status VARCHAR(30),payable_value DECIMAL(4,2),check_in_time TIME,check_out_time TIME,total_hours DECIMAL(5,2),remarks VARCHAR(600),UNIQUE KEY ux_daily(client_id,employee_id,attendance_date));
CREATE TABLE IF NOT EXISTS employee_monthly_attendance(id INT PRIMARY KEY AUTO_INCREMENT,client_id INT,employee_id INT,attendance_month VARCHAR(7),working_days DECIMAL(5,2),present_days DECIMAL(5,2),payable_days DECIMAL(5,2),lop_days DECIMAL(5,2),source_type VARCHAR(30),remarks VARCHAR(600),UNIQUE KEY ux_monthly(client_id,employee_id,attendance_month));
CREATE TABLE IF NOT EXISTS attendance_geo_fence_rules(id INT PRIMARY KEY AUTO_INCREMENT,client_id INT,name VARCHAR(180),scope_type VARCHAR(40),work_location_id INT NULL,latitude DECIMAL(10,7),longitude DECIMAL(10,7),radius_meters INT DEFAULT 100,gps_tolerance_meters INT DEFAULT 30,strictness VARCHAR(60) DEFAULT 'Block outside fence',allow_check_in BOOLEAN DEFAULT TRUE,allow_check_out BOOLEAN DEFAULT TRUE,effective_from DATE,effective_to DATE NULL,is_active BOOLEAN DEFAULT TRUE,priority INT DEFAULT 20);
CREATE TABLE IF NOT EXISTS attendance_geo_fence_rule_employees(geo_fence_rule_id INT,employee_id INT);
CREATE TABLE IF NOT EXISTS authusers(Id INT PRIMARY KEY,PasswordHash VARCHAR(255),ClientId INT NULL,EmployeeId INT NULL,IsActive BOOLEAN,MustChangePassword BOOLEAN);
CREATE TABLE IF NOT EXISTS auditlogs(Id BIGINT PRIMARY KEY AUTO_INCREMENT,UserId INT NULL,UserEmail VARCHAR(190),Action VARCHAR(120),Resource VARCHAR(190),Method VARCHAR(20),Path VARCHAR(500),StatusCode INT,IpAddress VARCHAR(80),UserAgent VARCHAR(500),DetailsJson JSON,CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS authsessions(Id BIGINT PRIMARY KEY AUTO_INCREMENT,UserId INT NOT NULL,TokenHash VARCHAR(64) NOT NULL,ExpiresAt DATETIME NOT NULL,RevokedAt DATETIME NULL);